/* WebAuthn (security key / passkey) ceremonies. Talks only to the JSON
 * endpoints the Go backend already exposes (/login/webauthn/*,
 * /portal/webauthn/register/*) — this is a straight port of the inline JS
 * that used to be generated by internal/server/webauthn.go. */

function b64urlToBuf(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  var bin = atob(s), buf = new Uint8Array(bin.length);
  for (var i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
}

function bufToB64url(buf) {
  var bytes = new Uint8Array(buf), bin = '';
  for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

/* Second-factor login: begin() -> navigator.credentials.get() -> finish().
 * `token` identifies the pending password-verified login (from the totp_token
 * hidden field); `onSuccess(data)` runs once the session cookie is set. */
async function useSecurityKeyLogin(token, msgEl, onSuccess) {
  msgEl.textContent = 'Waiting for your security key…';
  try {
    var beginRes = await fetch('/login/webauthn/begin', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: token }),
    });
    var begin = await beginRes.json();
    if (!beginRes.ok) { msgEl.textContent = begin.error || 'No security key available'; return; }
    var pk = begin.publicKey;
    pk.challenge = b64urlToBuf(pk.challenge);
    if (pk.allowCredentials) pk.allowCredentials.forEach(function (c) { c.id = b64urlToBuf(c.id); });
    var assertion = await navigator.credentials.get({ publicKey: pk });
    var credJSON = assertion.toJSON ? assertion.toJSON() : {
      id: assertion.id, rawId: bufToB64url(assertion.rawId), type: assertion.type,
      response: {
        clientDataJSON: bufToB64url(assertion.response.clientDataJSON),
        authenticatorData: bufToB64url(assertion.response.authenticatorData),
        signature: bufToB64url(assertion.response.signature),
        userHandle: assertion.response.userHandle ? bufToB64url(assertion.response.userHandle) : null,
      },
    };
    var finishRes = await fetch('/login/webauthn/finish', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: token, waToken: begin.waToken, credential: credJSON }),
    });
    var finish = await finishRes.json();
    if (!finishRes.ok) { msgEl.textContent = finish.error || 'Verification failed'; return; }
    onSuccess(finish);
  } catch (e) {
    msgEl.textContent = 'Security key error: ' + e.message;
  }
}

/* Portal "add a security key" ceremony: begin() -> navigator.credentials.create() -> finish(). */
async function registerSecurityKey(msgEl, onSuccess) {
  var name = prompt('Name this security key (e.g. "YubiKey", "Touch ID"):', 'Security key');
  if (name === null) return;
  msgEl.textContent = 'Waiting for your security key…';
  try {
    var beginRes = await fetch('/portal/webauthn/register/begin', { method: 'POST' });
    var begin = await beginRes.json();
    if (!beginRes.ok) { msgEl.textContent = begin.error || 'Could not start registration'; return; }
    var pk = begin.publicKey;
    pk.challenge = b64urlToBuf(pk.challenge);
    pk.user.id = b64urlToBuf(pk.user.id);
    if (pk.excludeCredentials) pk.excludeCredentials.forEach(function (c) { c.id = b64urlToBuf(c.id); });
    var cred = await navigator.credentials.create({ publicKey: pk });
    var credJSON = cred.toJSON ? cred.toJSON() : {
      id: cred.id, rawId: bufToB64url(cred.rawId), type: cred.type,
      response: {
        clientDataJSON: bufToB64url(cred.response.clientDataJSON),
        attestationObject: bufToB64url(cred.response.attestationObject),
      },
    };
    var finishRes = await fetch('/portal/webauthn/register/finish', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: begin.token, name: name, credential: credJSON }),
    });
    var finish = await finishRes.json();
    if (!finishRes.ok) { msgEl.textContent = finish.error || 'Registration failed'; return; }
    onSuccess();
  } catch (e) {
    msgEl.textContent = 'Error: ' + e.message;
  }
}
